#include <vector>

std::vector<int> latest_values(const std::vector<int>& xs, int capacity, int k) {
    std::vector<int> buf(capacity);
    unsigned count = 0;
    unsigned mask = capacity - 1;
    for (int x : xs) {
        buf[count & mask] = x;
        ++count;
    }
    int held = count < (unsigned)capacity ? (int)count : capacity;
    int take = k < held ? k : held;
    std::vector<int> out;
    for (int i = 0; i < take; ++i) {
        out.push_back(buf[(count - 1 - i) & mask]);
    }
    return out;
}
